          u2.trainBtn.replaceChildren(h("span.pt-ico", { html: iconSvg(primary[1], 18) }), primary[0]);
          u2.trainBtn.disabled = st2 === "starting" || st2 === "pausing";
          const second = st2 === "stopped" || st2 === "done" ? ["New run", "plus"] : ["Stop", "close"];
          u2.stopBtn.replaceChildren(h("span.pt-ico", { html: iconSvg(second[1], 18) }), second[0]);
          u2.stopBtn.disabled = st2 === "idle";
          const locked = !!memo2.run;
